create type user_role as enum ('student','admin');
create table profiles(id uuid primary key references auth.users on delete cascade, role user_role not null default 'student', full_name text, created_at timestamptz default now());
create table students(id uuid primary key references profiles on delete cascade, dob date, gender text, state text, district text, education_level text, course text, institution text, percentage numeric, cgpa numeric, annual_income numeric, is_st boolean, tribe_name text, disability boolean, first_gen boolean, consent_at timestamptz);
create table scholarships(id uuid primary key default gen_random_uuid(), title text not null, description text, provider text, category text, education_level text[], state text[], amount numeric, application_url text, deadline date, status text not null default 'draft' check (status in ('draft','published','archived')), income_limit numeric, minimum_percentage numeric, tribal_requirement boolean, gender_requirement text, disability_requirement boolean, required_documents text[] default '{}', benefits text, is_demo boolean default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table saved_scholarships(student_id uuid references students on delete cascade, scholarship_id uuid references scholarships on delete cascade, primary key(student_id,scholarship_id));
create table applications(id uuid primary key default gen_random_uuid(), student_id uuid not null references students on delete cascade, scholarship_id uuid not null references scholarships on delete cascade, status text not null default 'not_applied' check (status in ('not_applied','started','submitted','under_verification','approved','rejected')), notes text, updated_at timestamptz default now(), unique(student_id,scholarship_id));
create table notifications(id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, title text, body text, read_at timestamptz, created_at timestamptz default now());
create index on scholarships(status,deadline); create index on scholarships using gin(education_level); create index on applications(student_id,status);
create function is_admin() returns boolean language sql security definer stable as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); insert into public.students(id) values(new.id); return new; end $$;
create trigger on_signup after insert on auth.users for each row execute function public.handle_new_user();
alter table profiles enable row level security; alter table students enable row level security; alter table scholarships enable row level security; alter table saved_scholarships enable row level security; alter table applications enable row level security; alter table notifications enable row level security;
create policy p_read on profiles for select using (id=auth.uid() or is_admin());
create policy s_own on students for all using (id=auth.uid()) with check (id=auth.uid());
create policy s_admin_read on students for select using (is_admin());
create policy sch_read on scholarships for select using (status='published' or is_admin());
create policy sch_admin on scholarships for all using (is_admin()) with check (is_admin());
create policy sv_own on saved_scholarships for all using (student_id=auth.uid()) with check (student_id=auth.uid());
create policy app_own on applications for all using (student_id=auth.uid()) with check (student_id=auth.uid());
create policy app_admin on applications for all using (is_admin()) with check (is_admin());
create policy n_own on notifications for select using (user_id=auth.uid());
create policy n_upd on notifications for update using (user_id=auth.uid());
create policy n_admin on notifications for all using (is_admin()) with check (is_admin());
revoke update on profiles from authenticated, anon;
grant update(full_name) on profiles to authenticated;
